export function drawDataFlow(ctx,positions,w,h,time,eventId,selected,show,visual={}){
 const event=(visual.events||FLOW_EVENTS).find(x=>x.id===eventId)||FLOW_EVENTS[0],margin=12,gap=7,bw=(w-margin*2-gap*3)/4,centers=(visual.nodes||FLOW_NODES).map((n,i)=>({id:n.id,x:margin+i*(bw+gap)+bw/2,y:h-31}));const points={...positions};centers.forEach(p=>points[p.id]=p);
 if(show)for(const [edgeIndex,[from,to]] of event.edges.entries()){const a=points[from],b=points[to];if(!a||!b)continue;const blocked=(visual.haltCloud&&(from.startsWith('sys-')||to.startsWith('sys-')))||from===visual.blockNode||to===visual.blockNode;const bendY=from.startsWith('sys-')&&to.startsWith('sys-')?h-65-edgeIndex*10:(a.y+b.y)/2,bend={x:a.x,y:bendY},bend2={x:b.x,y:bendY};ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(bend.x,bend.y);ctx.lineTo(bend2.x,bend2.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=blocked?'#b6574d':event.color+'88';ctx.setLineDash(blocked?[5,4]:[]);ctx.lineWidth=2;ctx.stroke();ctx.setLineDash([]);
  const path=[a,bend,bend2,b],lengths=path.slice(1).map((p,i)=>Math.hypot(p.x-path[i].x,p.y-path[i].y)),total=lengths.reduce((s,x)=>s+x,0);for(let dot=0;!blocked&&dot<2;dot++){let travel=((time*.22+dot*.5)%1)*total,index=0;while(index<2&&travel>lengths[index]){travel-=lengths[index];index++;}const f=lengths[index]?travel/lengths[index]:0,p=path[index],q=path[index+1];ctx.beginPath();ctx.arc(p.x+(q.x-p.x)*f,p.y+(q.y-p.y)*f,4,0,Math.PI*2);ctx.fillStyle=event.color;ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=1;ctx.stroke();}
  const dx=b.x-bend2.x,dy=b.y-bend2.y,angle=Math.atan2(dy,dx);ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.lineTo(b.x-7*Math.cos(angle-.5),b.y-7*Math.sin(angle-.5));ctx.moveTo(b.x,b.y);ctx.lineTo(b.x-7*Math.cos(angle+.5),b.y-7*Math.sin(angle+.5));ctx.strokeStyle=blocked?'#b6574d':event.color;ctx.stroke();}
 if(visual.bufferNode&&points[visual.bufferNode]){const p=points[visual.bufferNode];ctx.fillStyle=visual.pending?'#b85e43':'#48795f';ctx.fillRect(p.x-30,p.y-27,70,20);ctx.font='bold 10px Arial';ctx.fillStyle='#fff';ctx.textAlign='center';ctx.fillText('QUEUE '+visual.pending,p.x+5,p.y-13);}
 const short=visual.shortNames||['POS','ERP','CRM/CDP','A/B'];for(let i=0;i<centers.length;i++){const p=centers[i];ctx.fillStyle=selected===p.id?'#f7dec8':'#fff';ctx.strokeStyle=selected===p.id?'#d58743':'#bdcdc1';ctx.lineWidth=1;ctx.fillRect(p.x-bw/2,p.y-15,bw,30);ctx.strokeRect(p.x-bw/2,p.y-15,bw,30);ctx.textAlign='center';ctx.font='bold '+(w<400?10:12)+'px Arial';ctx.fillStyle='#334f43';ctx.fillText(short[i],p.x,p.y+4);}
 return centers.map(p=>({id:p.id,minX:p.x-bw/2,maxX:p.x+bw/2,minY:p.y-15,maxY:p.y+15,depth:0}));
}
